def _header_for_script(ir: NotebookSerialization) -> str:
    """Extract a Python script-appropriate header string from the IR.

    For Python-origin notebooks, ``ir.header.value`` already holds the raw
    header text (which may contain a PEP 723 ``# /// script`` block and
    copyright comments), so it is returned verbatim.

    For Markdown-origin notebooks, ``ir.header.value`` holds YAML frontmatter
    instead of raw comment text. In that case we parse the frontmatter and
    reconstruct the PEP 723 header via ``get_headers_from_frontmatter``.
    """
    if ir.header is None:
        return ""

    value = ir.header.value
    if not value:
        return ""

    # Markdown-origin notebooks store YAML frontmatter in the header. Raw
    # Python comment headers parse to ``None`` under YAML, so a dict result
    # unambiguously identifies frontmatter.
    import yaml

    try:
        frontmatter = yaml.safe_load(value)
    except yaml.YAMLError:
        frontmatter = None

    if isinstance(frontmatter, dict):
        from marimo._utils.inline_script_metadata import (
            get_headers_from_frontmatter,
        )

        headers = get_headers_from_frontmatter(frontmatter)
        return headers["pyproject"] or headers["header"]

    return value


